changeSet.sql:
DELETE FROM dbs.dbs_daily_project
WHERE id IN (
    SELECT id FROM (
        SELECT id, row_number() OVER (
            PARTITION BY project_id, report_date
            ORDER BY recomputed_at DESC NULLS LAST, version DESC NULLS LAST, id DESC
        ) AS rn
        FROM dbs.dbs_daily_project
    ) d WHERE d.rn > 1
);

DELETE FROM dbs.dbs_daily_supervisor
WHERE id IN (
    SELECT id FROM (
        SELECT id, row_number() OVER (
            PARTITION BY project_id, supervisor_user_id, report_date
            ORDER BY recomputed_at DESC NULLS LAST, version DESC NULLS LAST, id DESC
        ) AS rn
        FROM dbs.dbs_daily_supervisor
    ) d WHERE d.rn > 1
);

ALTER TABLE dbs.dbs_daily_supervisor
    ADD CONSTRAINT uk_dbs_daily_sup_project_sup_date
    UNIQUE NULLS NOT DISTINCT (project_id, supervisor_user_id, report_date);

DELETE FROM dbs.dbs_daily_engineer
WHERE id IN (
    SELECT id FROM (
        SELECT id, row_number() OVER (
            PARTITION BY project_id, engineer_user_id, report_date
            ORDER BY recomputed_at DESC NULLS LAST, version DESC NULLS LAST, id DESC
        ) AS rn
        FROM dbs.dbs_daily_engineer
    ) d WHERE d.rn > 1
);

ALTER TABLE dbs.dbs_daily_engineer
    ADD CONSTRAINT uk_dbs_daily_eng_project_eng_date
    UNIQUE NULLS NOT DISTINCT (project_id, engineer_user_id, report_date);
